use std::collections::HashMap;

fn main() {
    // ---- Creating HashMaps ----
    let mut scores: HashMap<String, i32> = HashMap::new();
    let mut map = HashMap::from([
        ("Hero", 100),
        ("Aragorn", 85),
    ]);

    // ---- Inserting values ----
    scores.insert(String::from("Hero"), 100);
    scores.insert(String::from("Aragorn"), 85);
    scores.insert(String::from("Gandalf"), 95);

    // ---- Updating values ----
    scores.insert(String::from("Hero"), 120);  // Overwrites

    // ---- Accessing values ----
    let hero_score = scores.get("Hero");
    let missing = scores.get("Legolas");

    println!("Hero score: {:?}", hero_score);
    println!("Missing: {:?}", missing);

    // ---- Using unwrap_or ----
    let legolas_score = scores.get("Legolas").unwrap_or(&0);
    println!("Legolas score: {}", legolas_score);

    // ---- Iterating ----
    println!("\n=== Scores ===");
    for (name, score) in &scores {
        println!("{}: {}", name, score);
    }

    // ---- Updating if key exists ----
    scores.entry(String::from("Legolas")).or_insert(70);
    scores.entry(String::from("Hero")).or_insert(100);  // Doesn't change

    println!("\nAfter or_insert:");
    for (name, score) in &scores {
        println!("{}: {}", name, score);
    }

    // ---- Counting with HashMap ----
    let text = "hello world hello rust world hello";
    let mut word_count = HashMap::new();

    for word in text.split_whitespace() {
        let count = word_count.entry(word).or_insert(0);
        *count += 1;
    }

    println!("\nWord count: {:?}", word_count);

    // ---- HashMap with custom keys ----
    #[derive(Hash, Eq, PartialEq, Debug)]
    struct PlayerId(u32);

    let mut player_map: HashMap<PlayerId, String> = HashMap::new();
    player_map.insert(PlayerId(1), String::from("Hero"));
    player_map.insert(PlayerId(2), String::from("Aragorn"));

    println!("\nPlayer map: {:?}", player_map);

    // ---- Removing entries ----
    scores.remove("Gandalf");
    println!("\nAfter removing Gandalf: {:?}", scores);

    // ---- Check if empty ----
    println!("Is empty? {}", scores.is_empty());
    println!("Length: {}", scores.len());

    // ---- Clearing ----
    scores.clear();
    println!("After clear: {:?}", scores);
}

